def entry(key, evidence, profiles, rule, trigger, source_form, emitted_code, counterexample, examples, reference,
          mined=False):
    return {'id': key, 'class': evidence, 'profiles': profiles, 'rule': rule, 'trigger': trigger,
            'source_form': source_form, 'emitted_code': emitted_code, 'counter_example': counterexample,
            'examples': examples, 'reference': reference, 'mined_from_index': mined}


