def main():
    index = open_index()
    functions = {fn['function']: fn for fn in index['functions'] if fn['language'] == 'c'}
    for rule in RULES:
        evidence = []
        for name, pattern in rule['examples']:
            fn = functions[name]
            example = location(fn)
            example['entry'] = fn['oracle']
            if pattern is not None:
                spans = [s for s in fn['statements'] if re.search(pattern, s['text']) and s['instructions']]
                if not spans:
                    raise ValueError(f"{rule['id']}: no emitting STRICT span for {name} / {pattern}")
                for span in spans[:6 if rule['id'] == 'inline-context' and name == 'timerhandler' else 1]:
                    hit = statement_hit(fn, span)
                    evidence.append({**example, 'address': hit['address'], 'line': hit['line'], 'source_text': hit['text']})
            else:
                evidence.append(example)
        rule['examples'] = evidence
    dest = ROOT / 'docs'
    dump_json(dest / 'quirks.json', {'schema': 1, 'rules': RULES})
    lines = ['# Watcom 9.5 code generation in LameDuke', '',
             'This catalogue uses the DOS-hosted Watcom 9.5 GA `engine`, `game_oe`, and `multi` profiles. '
             'Apogee examples use the DOS-hosted Watcom 10.0 GA `audiolib` profile. The data-only `game` profile has no function examples.', '',
             '**PROVEN** denotes a scoped observation with STRICT examples, with DOS A/B or compiler trace evidence where cited. '
             '**STRONG** denotes a supported inference or a controlled observation with uncertain generality. '
             '**HYPOTHESIS** marks a possible explanation that still needs a matching control.', '',
             'Addresses are `obj:offset`. A source line is a compiler debug association. Scheduled and inlined sequences can '
             'include work from other statements. See [IDIOMS.md](IDIOMS.md) for instructions and validation.', '',
             '| Profile | Install | Default profile flags |', '|---|---|---|',
             '| `engine` | 9.5 GA | `-4r -s -or` |', '| `game_oe` | 9.5 GA | `-4r -s -otexan -oe=3000` |',
             '| `multi` | 9.5 GA | `-5r -s` |',
             '| `audiolib` | 10.0 GA | `-zq -w4 -d1 -omaxnet -zp4 -5r -DLIBVER_ASSREV=19950518` |', '',
             'GUS, GUSMIDI, and MULTIVOC have registered flag overrides. '
             'See [neutrality.json](../neutrality.json) for each unit’s effective flags.', '']
    for rule in RULES:
        lines.extend([f"## {rule['id'].replace('-', ' ').capitalize()}", '',
                      f"**{rule['class']}** · {', '.join(rule['profiles'])}", '',
                      rule['rule'], '', f"- **Conditions** — {rule['trigger']}",
                      f"- **Source form** — {rule['source_form']}", f"- **Emitted code** — {rule['emitted_code']}",
                      f"- **Counterexample or limit** — {rule['counter_example']}",
                      '- **STRICT examples** — ' + ', '.join(f"`{e['function']}` `{e['address']}`" +
                          (f" (`{e['source']}:{e['line']}`)" if 'line' in e else '') for e in rule['examples']),
                      f"- **Evidence** — {rule['reference']}", ''])
    (dest / 'WATCOM95_QUIRKS.md').write_text('\n'.join(lines), encoding='utf-8')
    from collections import Counter
    print(dict(Counter(r['class'] for r in RULES)), sum(r['mined_from_index'] for r in RULES), 'mined')


if __name__ == '__main__':
    main()
